use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &mut Vec<i32>)
    requires
        a.len() > 0,
    ensures
        a.len() == old(a.len()),
        // first becomes old last, last becomes old first
        a[0] == old(a[old(a.len()) - 1]),
        a[old(a.len()) - 1] == old(a[0]),
        // middle elements unchanged
        forall|i: int|
            0 < i && i < old(a.len()) - 1 ==> a[i] == old(a[i]),
{
    let n: usize = a.len();
    if n == 1 {
        // Nothing to do; postconditions follow trivially.
        return;
    }

    // Snapshot the endpoints before mutation
    let first: i32 = a[0];
    let last: i32 = a[n - 1];

    // Perform the swap in place
    a.set(0, last);
    a.set(n - 1, first);

    // Helpful assertions (not strictly necessary, but can aid verification)
    assert(a.len() == n);
    assert(a[0] == last);
    assert(a[n - 1] == first);
}

} // verus!

